package kicadactions

func engineeringActions() []ActionSpec {
	return []ActionSpec{
		{Name: "reference.search", Domain: DomainReference, Backend: BackendOffline, Description: "Search versioned KiCad engineering rules (Chinese/English): schematic, components, footprints, power, analog/clock, stackup, layout/routing, SI/PI/DDR/RF/EMC, safety, DFM/DFT and release. Retrieve only relevant cards with reference.get.", Inputs: []string{"query optional", "stage optional", "limit optional 1..20"}, Keywords: []string{"设计规范", "工业级", "参考", "原理图规范", "PCB标准"}},
		{Name: "reference.get", Domain: DomainReference, Backend: BackendOffline, Description: "Get a source-traceable engineering card: required inputs, policy rules, verification/evidence and authority/applicability limits. Expert teaching and examples are never normative certification.", Inputs: []string{"id (from reference.search)"}},
		{Name: "reference.plan", Domain: DomainReference, Backend: BackendOffline, Description: "Automatically call before relevant KiCad design/review/release work, without requiring a slash command. Return stage/query constraints, unknown-input policy and evidence gates; never invent universal trace widths, safety distances or Class 3 qualification.", Inputs: []string{"query optional (actual design task)", "stage optional (topic id or lifecycle stage)", "limit optional 1..20"}},
		{Name: "reference.examples", Domain: DomainReference, Backend: BackendOffline, Description: "Query ALL indexed original KiCad demo projects, including simulation projects; optionally return local relative files and indexed SHA-256. Examples are educational and not electrically qualified for production.", Inputs: []string{"query optional", "includeFiles optional boolean"}},
		{Name: "release.snapshot", Domain: DomainAudit, Backend: BackendOffline, Description: "Hash current local project design dependencies, nested schematics, libraries, 3D models, rules and manufacturing.json. Does not change the design. External dependency review remains required.", Inputs: []string{"project (directory with one project or full .kicad_pro)"}},
		{Name: "release.template", Domain: DomainAudit, Backend: BackendOffline, Description: "Return an intentionally pending revision-bound engineering evidence manifest for fabrication or production. Requires accountable reviews and real artifacts; no invented parameters or approvals.", Inputs: []string{"project", "target optional fabrication|production"}},
		{Name: "release.check", Domain: DomainAudit, Backend: BackendComposite, Description: "Read-only evidence gate: fresh native audit, complete design snapshot, manufacturer provenance, revision-bound review/test artifact hashes and applicable production evidence. Reports evidence completeness; never certifies people, physical tests or authorizes industrial production. Workflow booleans cannot bypass it.", Inputs: []string{"project", "manifest optional (JSON path; missing remains blocked)", "target optional fabrication|production"}, Keywords: []string{"投产", "量产", "投板", "工业级别", "验收", "放行"}},
	}
}
